<script setup lang="ts">
import {formatDate} from '../ui/branding'
import {onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message,type User} from '../api/client'
import {useAuth} from '../stores/auth'
const auth=useAuth(),rows=ref<User[]>([]),total=ref(0),page=ref(1),q=ref(''),status=ref(''),loading=ref(false),error=ref(''),dialog=ref(false),saving=ref(false),editing=ref<number|null>(null),credential=ref('')
const password=ref(''),confirmation=ref(''),resetDialog=ref(false),resetTarget=ref<User|null>(null),resetPassword=ref(''),resetConfirmation=ref(''),resetting=ref(false)
const blank=()=>({username:'',name:'',email:'',phone:'',remark:'',role:'user',status:'enabled',user_group_id:null as number|null})
const form=reactive(blank())
const groups=ref<{id:number,name:string,status:string,is_default:boolean}[]>([])
function groupName(id:number|null){return groups.value.find(g=>g.id===id)?.name||'未分配'}
const roles:Record<string,string>={super_admin:'超级管理员',admin:'管理员',user:'普通用户'}
async function load(){loading.value=true;error.value='';try{const r=(await api.get('/admin/users',{params:{page:page.value,q:q.value,status:status.value}})).data.data;rows.value=r.items;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(user?:User){password.value='';confirmation.value='';editing.value=user?.id||null;Object.assign(form,blank(),user?{username:user.username,name:user.name,email:user.email||'',phone:user.phone||'',remark:user.remark||'',role:user.role,status:user.status,user_group_id:user.user_group_id}:{});if(!user)form.user_group_id=groups.value.find(g=>g.is_default&&g.status==='enabled')?.id??null;dialog.value=true}
async function save(){if(!editing.value&&(!password.value||password.value!==confirmation.value||!form.user_group_id)){ElMessage.error('请填写一致的初始密码并选择用户组');return}saving.value=true;try{const payload={name:form.name,email:form.email||null,phone:form.phone||null,remark:form.remark,role:form.role,status:form.status,user_group_id:form.user_group_id};if(editing.value){await api.patch('/admin/users/'+editing.value,payload);ElMessage.success('用户已更新')}else{const r=(await api.post('/admin/users',{...payload,username:form.username,password:password.value,password_confirmation:confirmation.value})).data.data;credential.value=r.initial_password}dialog.value=false;await load()}catch(e){ElMessage.error(message(e))}finally{saving.value=false}}
async function toggle(user:User){try{await api.patch('/admin/users/'+user.id,{name:user.name,email:user.email,phone:user.phone,role:user.role,status:user.status==='enabled'?'disabled':'enabled',user_group_id:user.user_group_id});await load()}catch(e){ElMessage.error(message(e))}}
async function remove(user:User){try{await ElMessageBox.confirm('删除用户后立即停止登录，历史记录保留。','删除 '+user.username,{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await api.delete('/admin/users/'+user.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
function reset(user:User){resetTarget.value=user;resetPassword.value='';resetConfirmation.value='';resetDialog.value=true}
async function saveReset(){if(!resetTarget.value||!resetPassword.value||resetPassword.value!==resetConfirmation.value){ElMessage.error('请填写一致的密码');return}resetting.value=true;try{await api.post('/admin/users/'+resetTarget.value.id+'/reset-password',{password:resetPassword.value,password_confirmation:resetConfirmation.value});resetDialog.value=false;ElMessage.success('密码已重置，用户下次登录需改密');await load()}catch(e){ElMessage.error(message(e))}finally{resetting.value=false}}
async function unlock(user:User){try{await api.post('/admin/users/'+user.id+'/unlock');ElMessage.success('账号已解锁');await load()}catch(e){ElMessage.error(message(e))}}onMounted(async()=>{await load();try{groups.value=(await api.get('/admin/user-group-options')).data.data}catch(e){error.value=message(e)}})
</script>
<template><div><PageHeader title="用户管理" description="管理账号状态、角色和个人资料。"><el-button type="primary" @click="open()">新增用户</el-button></PageHeader><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="panel"><div class="toolbar"><el-input v-model="q" placeholder="搜索用户名或姓名" style="width:240px" clearable @keyup.enter="page=1;load()"/><el-select v-model="status" placeholder="全部状态" clearable style="width:150px"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select><el-button @click="page=1;load()">查询</el-button></div><el-table :data="rows" v-loading="loading" empty-text="暂无用户"><el-table-column label="用户名" min-width="160"><template #default="s"><router-link :to="'/admin/users/'+s.row.id" style="color:var(--el-color-primary)">{{s.row.username}}</router-link></template></el-table-column><el-table-column prop="name" label="姓名" min-width="140"/><el-table-column label="角色" width="130"><template #default="s">{{roles[s.row.role]||s.row.role}}</template></el-table-column><el-table-column label="用户组" min-width="130"><template #default="s">{{groupName(s.row.user_group_id)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='enabled'?'success':'info'">{{s.row.status==='enabled'?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="登录锁定" width="130"><template #default="s"><span v-if="s.row.login_locked">已锁定 · {{s.row.lock_remaining_seconds}}秒</span><span v-else>{{s.row.login_locked===null?'未知':'正常'}}</span></template></el-table-column><el-table-column prop="remark" label="备注" min-width="140"/><el-table-column label="最近登录" min-width="170"><template #default="s">{{s.row.last_login_at?formatDate(s.row.last_login_at):'尚未登录'}}</template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="s">{{formatDate(s.row.created_at)}}</template></el-table-column><el-table-column label="操作" width="310" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link @click="reset(s.row)">重置密码</el-button><el-button v-if="s.row.login_locked" link @click="unlock(s.row)">解锁</el-button><el-button link :disabled="s.row.id===auth.user?.id" @click="toggle(s.row)">{{s.row.status==='enabled'?'禁用':'启用'}}</el-button><el-button link type="danger" :disabled="s.row.id===auth.user?.id" @click="remove(s.row)">删除</el-button></template></el-table-column><template #empty><EmptyState title="暂无用户" description="检查筛选条件、时间范围或相关配置后重试。"/></template></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" style="margin-top:24px" @current-change="load"/></div><el-drawer v-model="dialog" :title="editing?'编辑用户':'新增用户'" size="640px" @closed="password='' ;confirmation=''"><el-form label-width="90px"><el-form-item label="用户名"><el-input v-model="form.username" :disabled="!!editing" maxlength="80"/></el-form-item><el-form-item v-if="!editing" label="初始密码" required><el-input v-model="password" type="password" autocomplete="new-password" maxlength="128"/></el-form-item><el-form-item v-if="!editing" label="确认密码" required><el-input v-model="confirmation" type="password" autocomplete="new-password" maxlength="128"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" maxlength="254"/></el-form-item><el-form-item label="手机号"><el-input v-model="form.phone" maxlength="30"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="普通用户" value="user"/><el-option v-if="auth.user?.role==='super_admin'" label="管理员" value="admin"/><el-option v-if="auth.user?.role==='super_admin'" label="超级管理员" value="super_admin"/></el-select></el-form-item><el-form-item label="用户组"><el-select v-model="form.user_group_id" clearable placeholder="未分配" @clear="form.user_group_id=null"><el-option v-for="g in groups" :key="g.id" :value="g.id" :label="g.name+(g.is_default?'（默认）':g.status==='disabled'?'（已禁用）':'')"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="enabled"/><el-option label="禁用" value="disabled"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="2000"/></el-form-item><p v-if="!editing" class="muted">密码至少12位，包含大小写字母、数字、符号中的三类。用户首次登录必须改密。</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-drawer><el-drawer v-model="resetDialog" :title="'重置密码 · '+(resetTarget?.username??'')" size="480px" @closed="resetPassword='';resetConfirmation=''"><el-form label-position="top"><el-form-item label="新密码" required><el-input v-model="resetPassword" type="password" autocomplete="new-password" maxlength="128"/></el-form-item><el-form-item label="确认新密码" required><el-input v-model="resetConfirmation" type="password" autocomplete="new-password" maxlength="128"/></el-form-item><p class="muted">保存后撤销该用户全部会话，下次登录需改密。密码至少12位，包含三类字符。</p></el-form><template #footer><el-button @click="resetDialog=false">取消</el-button><el-button type="primary" :loading="resetting" @click="saveReset">保存</el-button></template></el-drawer><el-dialog :model-value="!!credential" title="临时登录密码" width="500px" @close="credential='' "><p>请立即复制并安全交付给用户。关闭后无法再次查看。</p><div class="credential">{{credential}}</div><template #footer><el-button type="primary" @click="credential=''">已记录，关闭</el-button></template></el-dialog></div></template>


